using AutoPecasERP.Core.Entities; using AutoPecasERP.Data.Context; using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Services.Compras;
public class CompraService { readonly ErpDbContext db; public CompraService(ErpDbContext db)=>this.db=db;
 public async Task ReceberAsync(int pedidoId,string usuario="Sistema"){var p=await db.PedidosCompra.Include(x=>x.Itens).ThenInclude(x=>x.Produto).Include(x=>x.Fornecedor).FirstAsync(x=>x.Id==pedidoId); if(p.Status=="Recebido") throw new InvalidOperationException("Pedido já recebido."); decimal recebido=0; foreach(var i in p.Itens){var qtd=i.Quantidade-i.QuantidadeRecebida;if(qtd<=0||i.Produto is null)continue;var anterior=i.Produto.EstoqueAtual;i.Produto.EstoqueAtual+=qtd;i.QuantidadeRecebida+=qtd;db.MovimentacoesEstoque.Add(new MovimentacaoEstoque{ProdutoId=i.ProdutoId,Tipo="Entrada Compra",Quantidade=qtd,SaldoAnterior=anterior,SaldoPosterior=i.Produto.EstoqueAtual,Documento=p.Numero,Observacao="Recebimento de pedido de compra"});if(i.Produto.Custo!=i.CustoUnitario){db.HistoricosCusto.Add(new HistoricoCusto{ProdutoId=i.ProdutoId,CustoAnterior=i.Produto.Custo,CustoNovo=i.CustoUnitario,Documento=p.Numero});i.Produto.Custo=i.CustoUnitario;}recebido+=qtd*i.CustoUnitario;} p.Status="Recebido"; if(p.Fornecedor!=null)p.Fornecedor.UltimaCompra=DateTime.Now; if(recebido>0)db.ContasPagar.Add(new ContaPagar{FornecedorId=p.FornecedorId,PedidoCompraId=p.Id,Descricao=$"Pedido {p.Numero}",Valor=recebido+p.Frete-p.Desconto,Vencimento=DateTime.Today.AddDays(30)});db.Auditorias.Add(new Auditoria{Usuario=usuario,Acao="Recebimento",Entidade="PedidoCompra",Referencia=p.Numero,Detalhes=$"Valor recebido: {recebido:N2}"});await db.SaveChangesAsync();}
}
